"""SplitMix64: golden vectors from the original C reference, plus the
helpers the organism and town rely on."""
import unittest

from aethel_pkg.rng import DEFAULT_SEED, SplitMix64, Streams, fnv1a64

# Generated by the reference C implementation (Vigna's splitmix64),
# compiled with gcc -O2; see rng.py's docstring.
GOLDEN = {
    0:  [0xE220A8397B1DCDAF, 0x6E789E6AA1B965F4,
         0x06C45D188009454F, 0xF88BB8A8724C81EC],
    1:  [0x910A2DEC89025CC1, 0xBEEB8DA1658EEC67,
         0xF893A2EEFB32555E, 0x71C18690EE42C90B],
    42: [0xBDD732262FEB6E95, 0x28EFE333B266F103,
         0x47526757130F9F52, 0x581CE1FF0E4AE394],
    0xDEADBEEFCAFEBABE: [0x0D7D93560D1929D2, 0x491DFB740E50D43F,
                         0x42722BF4473E5E7D, 0xD6CA8A0790FFFC45],
}


class TestGoldenVectors(unittest.TestCase):
    def test_reference_vectors(self):
        for seed, expected in GOLDEN.items():
            r = SplitMix64(seed)
            got = [r.next_uint64() for _ in range(len(expected))]
            self.assertEqual(got, expected, f"seed {seed:#x}")

    def test_same_seed_same_sequence(self):
        a, b = SplitMix64(1234), SplitMix64(1234)
        self.assertEqual([a.next_uint64() for _ in range(100)],
                         [b.next_uint64() for _ in range(100)])


class TestHelpers(unittest.TestCase):
    def test_random_unit_interval(self):
        r = SplitMix64(9)
        xs = [r.random() for _ in range(5000)]
        self.assertTrue(all(0.0 <= x < 1.0 for x in xs))
        self.assertAlmostEqual(sum(xs) / len(xs), 0.5, delta=0.02)

    def test_randint_bounds_and_inclusivity(self):
        r = SplitMix64(3)
        seen = {r.randint(1, 3) for _ in range(200)}
        self.assertEqual(seen, {1, 2, 3})  # inclusive both ends

    def test_sample_unique_and_bounded(self):
        r = SplitMix64(5)
        s = r.sample(range(100), 10)
        self.assertEqual(len(s), 10)
        self.assertEqual(len(set(s)), 10)
        with self.assertRaises(ValueError):
            r.sample([1, 2], 3)

    def test_shuffle_is_permutation(self):
        r = SplitMix64(6)
        lst = list(range(50))
        r.shuffle(lst)
        self.assertEqual(sorted(lst), list(range(50)))

    def test_weighted_choice_proportions(self):
        r = SplitMix64(7)
        counts = {0: 0, 1: 0, 2: 0}
        for _ in range(20000):
            counts[r.weighted_choice([0, 1, 2], [1.0, 2.0, 3.0])] += 1
        total = sum(counts.values())
        self.assertAlmostEqual(counts[0] / total, 1 / 6, delta=0.02)
        self.assertAlmostEqual(counts[2] / total, 3 / 6, delta=0.02)


class TestStreams(unittest.TestCase):
    def test_spawn_is_deterministic(self):
        a = SplitMix64(42).spawn("dreams")
        b = SplitMix64(42).spawn("dreams")
        self.assertEqual([a.next_uint64() for _ in range(10)],
                         [b.next_uint64() for _ in range(10)])

    def test_streams_are_independent(self):
        s = Streams(DEFAULT_SEED)
        self.assertNotEqual(s.stream("dreams").get_state(),
                            s.stream("town").get_state())
        self.assertIs(s.stream("dreams"), s.stream("dreams"))

    def test_fnv1a64_is_stable(self):
        # Cross-platform: never Python's per-process hash().
        self.assertEqual(fnv1a64("dreams"), fnv1a64("dreams"))
        self.assertNotEqual(fnv1a64("dreams"), fnv1a64("town"))

    def test_state_roundtrip_continues_sequence(self):
        a = SplitMix64(42)
        a.next_uint64(); a.next_uint64()
        saved = a.get_state()
        b = SplitMix64(0)
        b.set_state(saved)
        self.assertEqual([a.next_uint64() for _ in range(20)],
                         [b.next_uint64() for _ in range(20)])


if __name__ == "__main__":
    unittest.main()
